"""Turn tools/patches.json into src/lib/talk/patches.ts.

Where each patch sits in her frame is measured, not chosen, so it is written by the tool that
measured it rather than copied by hand into the source.

Run:  python -I tools/write-patches-ts.py      (compose-visemes.py runs it for you)
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "src", "lib", "talk", "patches.ts")

HEAD = """/*
 * GENERATED by tools/write-patches-ts.py from tools/patches.json -- do not edit by hand.
 *
 * Where each cut-out sits inside the 1254-pixel square of the front frame, and how well it sits
 * there: `seam` is the mean colour difference in the ring of skin just outside the cut, which is
 * what a visible join would be. Anything under about 12 is invisible on screen.
 */

import type { Patch } from './frames';

export interface MeasuredPatch extends Patch {
  /** Mean colour difference in the skin just outside the cut, 0 to 441. */
  seam: number;
}

"""


def main():
    with open(os.path.join(HERE, "patches.json")) as fh:
        p = json.load(fh)
    lines = [HEAD]
    for name in sorted(p):
        r = p[name]
        key = name.replace("-", "_").upper()
        lines.append(
            f"export const {key}: MeasuredPatch = {{\n"
            f"  src: '/images/frames/{name}.webp',\n"
            f"  x: {r['x']},\n  y: {r['y']},\n  w: {r['w']},\n  h: {r['h']},\n"
            f"  seam: {r['seam']},\n}};\n\n"
        )
    with open(OUT, "w", newline="\n") as fh:
        fh.write("".join(lines).rstrip() + "\n")
    print(f"wrote {os.path.normpath(OUT)} ({len(p)} patches)")


if __name__ == "__main__":
    main()
